def h(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def w(name,data):(O/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n')
def bind(p):return dict(path=str(p.relative_to(R)),sha256=h(p),bytes=p.stat().st_size)
