assert probes['status']=='PASS'
render=j(O/'independent-render-and-fingerprints.json')
head=H['canonicalOriginal']['head']
canonical=json.loads(subprocess.check_output(['git','show',head+':'+H['canonicalOriginal']['path']],cwd=R));by={g['id']:g for g in canonical['goals']}
ids=[f['goalId'] for f in H['forms']]
atomicReasons={
ids[0]:'Eine zusammenhängende Entscheidungskompetenz: dieselbe Inspektionsregel aus Ereignismodell, zwei Fehlergrenzen und erwartetem Aufwand begründet auswählen. Feste und adaptive Entwürfe sind Vergleichsfälle derselben Kernhandlung; die Modellkritik kontrolliert deren Geltungsbereich. Keine unabhängigen neuen curricularen Ziele entstehen.',
ids[1]:'Eine zusammenhängende Symmetrieprüfung desselben Polynomvertrags. Identitätsrechnung und Koeffizientenstruktur sind zwei ausdrücklich verlangte Begründungsweisen derselben Eigenschaft, keine zu trennenden Lernziele. Konstanten, Nullpolynom und Gegenbeispiele prüfen die Reichweite derselben Regel.',
ids[2]:'Eine inverse Graphinterpretation: aus beobachteten Merkmalen Grad oder passenden Term herleiten und die Informationsgrenzen prüfen. Ablesen, Vielfachheit, Gradschluss, Faktorbestimmung und Gegenkonstruktion sind Teilschritte dieser Kompetenz. Der Vertrag ist disjunktiv; kein zusätzliches getrenntes Grad- und Termbestehen.',
ids[3]:'Eine Transformationskompetenz über bekannte Funktionsklassen hinweg. Verschiebung sowie vertikale und horizontale Skalierung werden durch dieselbe Parameter-zu-Punktabbildung und ihre Graphmerkmale erklärt. Die drei Klassen sind Prüfbeispiele dieser gemeinsamen Operation, keine Erweiterung auf unabhängige Kurvendiskussion, Integration oder wechselnde Funktionstypen.'}
memoryReasons={
ids[0]:'Die zu prüfende Leistung ist kontextabhängige Modellbildung und begründete Regelentscheidung; Binomialwerte dürfen berechnet werden. Kein eigenes Deck für die konkreten Schwellen, Zahlen oder diese eine Inspektionsregel. Ein gegebenenfalls anderswo begründeter Formelabruf wird hier nicht neu als Memory-Pflicht eingeführt.',
ids[1]:'Die Identitäten und Exponentenregeln werden an Termauswertung und Gegenbeispielen verstanden und angewandt. Ein zusätzliches Deck ist für dieses Anwendungsziel nicht notwendig; bloßes Abrufen der Wörter gerade/ungerade wird ausdrücklich nicht als Kompetenznachweis gewertet.',
ids[2]:'Die entscheidende Leistung ist Auswertung einer konkreten Grafik mit begründeter Modellwahl und Unsicherheitsgrenze. Weder Punktkoordinaten noch der Beispielterm sind dauerhafte Abrufgegenstände. Kein eigenes Memory-Deck gerechtfertigt.',
ids[3]:'Parameterwirkungen werden aus Punktkoordinaten algebraisch oder geometrisch hergeleitet. Ein Deck für diese exemplarischen Parameterwerte und Merkmalslisten würde die geprüfte Begründungsleistung nicht ersetzen. Keine eigenständige notwendige Abrufliste entsteht.'}

manualCases=[]
def case(gid,name,work,credits,cap,reason):
 steps=j(P/gid/'proposed-whole-goal.draft.json')['examData']['scoring']['steps']
 assert len(credits)==len(steps) and all(0<=c<=st['points'] for c,st in zip(credits,steps))
 raw=sum(credits);total=min(raw,14) if cap else raw
 manualCases.append(dict(goalId=gid,case=name,concreteSubmittedWork=work,criterionCredits=[dict(id=st['id'],credit=c,maximum=st['points']) for st,c in zip(steps,credits)],capApplies=cap,rawPoints=raw,finalPoints=total,passed=total>=15,reviewerReason=reason))
case(ids[0],'Alternative vollständige Enumeration','Die Abgabe definiert für alle x,y in 0..20 den Indikator I=1 bei x>=r oder 3<=x<r und x+y>=8, multipliziert die beiden Binomialmassen, summiert I und 20+20*1[3<=x<r] und begründet die Wahl r=6. Sie nennt außerdem 5/8 als minimale feste Schwellen, die jeweiligen Vorgängerwahrscheinlichkeiten, alle vier adaptiven Werte, alle Grenzfälle und die Modellannahmen.',[1,2,2,3,3,2,2,3,2],False,'Vollständige gleichwertige Fallrechnung, ohne dass eine benannte Tail-Funktion verlangt werden darf.')
case(ids[0],'14: fehlende feste 40er-Teststärke und Aufwand','Alle Schwellen mit Vorgängerprüfung, gesamte adaptive Ereignisrechnung, alle vier adaptiven Wahrscheinlichkeiten und Stop-Abweichungen sind richtig. Für n=20 wird die Teststärke berechnet; die feste 40er-Teststärke fehlt. r=6 wird mit vollständiger Regel und beiden adaptiven Grenzen gewählt. Aufwand und Schlussfrage bleiben leer.',[1,2,1,3,3,2,0,2,0],False,'Die zentrale begründete Regel liegt vor. Fehlende Nebenergebnisse ergeben 14, kein Bestehen und keine künstliche Teilgrenze.')
case(ids[0],'15: feste 40er-Teststärke ergänzt','Wie der vorherige Fall; zusätzlich steht P_0.30(Bin(40,p)>=8)=0.944717, sodass die feste 40er-Regel beide Grenzen erfüllt. Die Aufwandsrechnung und Schlussfrage fehlen weiterhin.',[1,2,2,3,3,2,0,2,0],False,'Genau 15 mit tragfähigem Gesamtereignis und Entscheidung. Der Vertrag verlangt keine zusätzliche ungeschriebene Effizienz-Teilbestehensgrenze.')
case(ids[0],'Falsche feste Gesamtschwelle für adaptiven Plan','Die festen Rechnungen sind vollständig. Für beide r nennt die Abgabe nur die Bin(40,p)-Schwelle 8 und dieselben Werte 0.041902/0.944717. Sie formuliert die r=6-Handlungsfälle und berechnet E(N) korrekt sowie zwei Modellgrenzen, liefert jedoch keine adaptive Ereignisprüfung und begründet die adaptive Wahl ausschließlich durch die falsche feste Verteilung.',[1,2,2,0,0,0,2,1,2],True,'Das ist keine bloße Zahlabweichung: x=6,y=0 und x=2,y=10 widerlegen das verwendete Ereignis. Die gesamte adaptive Regel bleibt mathematisch unbegründet.')

case(ids[1],'Direktes Vertauschen der Quadrate','Vollständige sonstige Lösung; bei u wird u(-x)=(-x+1)^2+(-x-1)^2=(x-1)^2+(x+1)^2=u(x) geschrieben, u(0)=2 schließt Ursprungssymmetrie aus. Die gleichwertige Strukturbegründung ist das Vertauschen der beiden Summanden.',[3,3,3,4,3,4],False,'Erweiterung in Einzelmonome ist nicht die einzig zulässige Strukturprüfung.')
case(ids[1],'14: h nur eingesetzt, keine beiden Schlussbehauptungen','f und g werden vollständig rechnerisch und strukturell geprüft. Bei h steht nur h(-x)=x^4-x^3-2, ohne Schluss. u wird vollständig durch Expansion und Identität geprüft; beide allgemeinen Koeffizientenregeln, v und z sind richtig. Beide Schlussbehauptungen bleiben unbeantwortet.',[3,3,1,4,3,0],False,'Beide geforderten Prüfweisen sind schon bei f,g sichtbar. Fehlende Antworten bleiben normale Punktverluste.')
case(ids[1],'15: beide h-Identitäten verworfen','Wie vorher, zusätzlich wird h(-x) mit h(x) und -h(x) verglichen und beide Identitäten werden richtig verworfen. Eine gesonderte Aussage über den gemischten geraden/ungeraden Anteil fehlt weiterhin.',[3,3,2,4,3,0],False,'Die begründeten Symmetrieentscheidungen ergänzen genau 1 BE; die eine 15er-Schwelle entscheidet.')
case(ids[1],'Nur richtige Etiketten','Es stehen f:y-Achse, g:Ursprung, h:keines, u:y-Achse, v:y-Achse, z:beide, aber keine Rechnung, keine Strukturbegründung, keine Regel und keine Gegenbeispiele.',[0.5,0.5,0.5,0.5,1.5,0],True,'Richtige Einordnungen erhalten begrenzten Teilkredit; keine der beiden verpflichtenden Begründungsweisen ist nachgewiesen.')

case(ids[2],'Alternative über Koeffizienten','Vollständige Graphauswertung mit Grad 3; die Abgabe nutzt ax^3+bx^2+cx+d, F(-2)=0,F(1)=0,F(0)=1 sowie die doppelte Nullstelle bei 1 und erhält a=1/2,b=0,c=-3/2,d=1. Sie kontrolliert Vorzeichen und konstruiert F(x)(1+x^2) bei reduzierten Daten.',[2,2,4,5,3,4],False,'Gleichwertiger Rechenweg ist zulässig. Ableitungen sind nicht erforderlich, aber auch nicht verboten.')
case(ids[2],'14: nur erste Bildkontrolle','Graphdaten, Vielfachheiten, Gradbegründung mit Enden/oberer Grenze und Termbestimmung sind vollständig. Danach wird nur die Kreuzung bei -2 mit Vorzeichen von x+2 begründet; Berührung, Intervallvorzeichen und Teil 5 fehlen.',[2,2,4,5,1,0],False,'Die inverse Graphkompetenz ist unzweifelhaft gezeigt; 14 bleiben dennoch unter der Gesamtgrenze.')
case(ids[2],'15: Berührung als weitere Kontrolle','Wie zuvor; zusätzlich erklärt die Abgabe die gerade Vielfachheit bei 1 mit einem beiderseits nicht negativen Quadrat und positivem Faktor x+2. Vorzeichenintervall und Teil 5 fehlen weiterhin.',[2,2,4,5,2,0],False,'Genau 15. Eine separate Pflicht zur Gegenkonstruktion würde die veröffentlichte Gesamtbewertung verschärfen.')
case(ids[2],'Ein allein abgeschriebener Term','Die ganze Abgabe besteht aus F(x)=0.5(x+2)(x-1)^2. Kein Ablesen, kein Ansatz, kein Faktorbestimmen, kein Gradargument und keine Kontrolle.',[0,0,0,1,0,0],True,'Ein zufällig richtiger Endterm ist kein nachgewiesener Rückschluss aus dem Bild.')

case(ids[3],'Geometrisch begründete vollständige Antwort','Alle Merkmale und konkreten Werte sind richtig. Die Abgabe beschreibt eine starre Translation um (t,1), Multiplikation jeder Ordinate mit a und Division jeder Abszisse durch b; sie setzt die so erhaltenen Koordinaten in die jeweilige Funktion ein und liefert zwei zulässige Gegenbeispiele.',[2,4,2,4,2,4,2],False,'Kein bestimmter Theoremname und kein Computerplot verlangt; geometrische und algebraische Begründung sind gleichwertig.')
case(ids[3],'14: zwei Familien vollständig, Sinus nur allgemeine Merkmale','G_t und H_a sind einschließlich Punktabbildung, Parameterrichtung, Merkmalen, konkreten Werten und Nichtschneiden vollständig. Bei K_b stehen nur Wertebereich [-1,1], Amplitude 1, Periode 2pi/b und Nullstellen k*pi/b. Keine Punktabbildung, keine konkrete Periode/Maxima und keine Schlussbeispiele.',[2,4,2,4,0,2,0],False,'Die zentrale Begründung ist in zwei Familien präsent. Der unvollständige Sinusteil führt zu normalem Punkteabzug.')
case(ids[3],'15: ein konkretes Sinuspaar ergänzt','Wie zuvor, zusätzlich werden für b=2 korrekt Periode pi und erster Hochpunkt (pi/4,1) genannt. Andere fehlende Angaben bleiben leer.',[2,4,2,4,0,3,0],False,'Genau 15. Es gibt keine separate Mindestleistung pro Funktionsklasse.')
case(ids[3],'Merkmallisten ohne Parametermechanismus','Nur richtige Definitions-/Wertebereiche, Scheitel, Achse, konkrete Scheitel, Achsenabschnitte, Asymptote, Werte bei x=0 sowie Sinusperioden/Nullstellen/Maxima. Weder Punktabbildung noch Unterscheidung der festen und variablen Translation, keine Schnittpunktbegründung, keine Wirkungsbegründung oder Schlussbeispiele.',[0,3.5,0,3,0,4,0],True,'Kein tragfähiger Zusammenhang zwischen Parameter und Graphänderung; auswendig richtige Listen reichen nicht.')
w('independent-rubric-cases.json',dict(status='REVIEWER_AUTHORED_MANUAL_SEMANTIC_CASES_ARITHMETIC_CHECKED',caseCount=len(manualCases),cases=manualCases,limits='Manual evaluation of explicit synthetic submissions, not an automatic semantic grader and not learner data. All 32 author cases were separately read; their generic boundary narratives do not become independent evidence.'))

